function validate(input) {
  const [producers, consumers, operations, args] = input;
  if (!Number.isInteger(producers) || producers < 1 || producers > 8) return 'producers must be an integer from 1 to 8.';
  if (!Number.isInteger(consumers) || consumers < 1 || consumers > 8) return 'consumers must be an integer from 1 to 8.';
  if (operations.length !== args.length) return 'operations and args must have the same length.';
  if (operations[0] !== 'BoundedBlockingQueue' || args[0].length !== 1) return 'Start with "BoundedBlockingQueue" and [capacity].';
  const capacity = args[0][0];
  if (capacity < 1 || capacity > 30) return 'capacity must be from 1 to 30.';
  if (operations.length < 2 || operations.length > 41) return 'Make 1 to 40 calls after the constructor.';
  let enqueues = 0, dequeues = 0;
  for (let i = 1; i < operations.length; i++) {
    if (operations[i] === 'enqueue') {
      if (args[i].length !== 1 || args[i][0] < 0 || args[i][0] > 20) return 'enqueue takes one element from 0 to 20.';
      enqueues++;
    } else if (operations[i] === 'dequeue') {
      if (args[i].length !== 0) return 'dequeue takes no arguments.';
      dequeues++;
    } else return 'Each call after the constructor is "enqueue" or "dequeue".';
  }
  if (dequeues > enqueues) return 'There must be at least as many enqueue calls as dequeue calls.';
  if (enqueues - dequeues > capacity) return 'At most capacity more enqueues than dequeues, or a producer would wait forever.';
  return null;
}

