function adapt(input, solve, kit) {
  const [producers, consumers, operations, args] = input;
  const queue = new solve(args[0][0]);
  for (const name of ['enqueue', 'dequeue', 'size']) if (!queue || typeof queue[name] !== 'function') throw new Error(`BoundedBlockingQueue needs a method ${name}.`);
  const threads = [
    ...Array.from({ length: producers }, (_, i) => ({ name: `Producer ${i + 1}`, calls: [] })),
    ...Array.from({ length: consumers }, (_, i) => ({ name: `Consumer ${i + 1}`, calls: [] })),
  ];
  let enqueues = 0, dequeues = 0;
  for (let i = 1; i < operations.length; i++) {
    if (operations[i] === 'enqueue') threads[enqueues++ % producers].calls.push(i);
    else threads[producers + (dequeues++ % consumers)].calls.push(i);
  }
  const values = [], times = operations.slice(1).map(() => null);
  let failure = null;
  // Each thread makes its calls one after another, call i no earlier than i ms.
  const run = async (thread) => {
    for (const i of thread.calls) {
      if (Date.now() < i) await new Promise((resolve) => setTimeout(resolve, i - Date.now()));
      if (operations[i] === 'enqueue') {
        kit.trace(`${thread.name} calls enqueue(${args[i][0]})`);
        await queue.enqueue(args[i][0]);
        kit.trace(`enqueue(${args[i][0]}) returns in ${thread.name}`);
      } else {
        kit.trace(`${thread.name} calls dequeue()`);
        const value = await queue.dequeue();
        values[i] = value === undefined ? null : value;
        kit.trace(`dequeue() returns ${value} in ${thread.name}`);
      }
      times[i - 1] = Date.now();
    }
  };
  for (const thread of threads) run(thread).catch((error) => { failure = failure ?? `${thread.name} failed: ${error && error.message || error}`; });
  // A correct solution has returned from every call by the last call's time; a call still waiting keeps null.
  return new Promise((resolve, reject) => setTimeout(() => {
    if (failure) return reject(new Error(failure));
    Promise.resolve(queue.size()).then((size) => {
      kit.trace(`size() returns ${size}`);
      const output = operations.flatMap((op, i) => (op === 'dequeue' ? [values[i] ?? null] : []));
      resolve({ output: [...output, size], times });
    }, reject);
  }, operations.length));
}

