class BoundedBlockingQueue {
  constructor(capacity) {
    this.capacity = capacity;
    this.items = [];
    this.waitingProducers = [];
    this.waitingConsumers = [];
  }

  async enqueue(element) {
    while (this.items.length === this.capacity) {
      await new Promise((resolve) => this.waitingProducers.push(resolve));
    }
    this.items.push(element);
    const wake = this.waitingConsumers.shift();
    if (wake) wake();
  }

  async dequeue() {
    while (this.items.length === 0) {
      await new Promise((resolve) => this.waitingConsumers.push(resolve));
    }
    const element = this.items.shift();
    const wake = this.waitingProducers.shift();
    if (wake) wake();
    return element;
  }

  size() {
    return this.items.length;
  }
}

