class BoundedBlockingQueue {
  constructor(capacity) {
    this.capacity = capacity;
    this.items = [];
    this.requests = [];
  }

  // Grant pending requests, oldest first, for as long as one of them can go ahead.
  serve() {
    for (let moved = true; moved; ) {
      moved = false;
      const put = this.requests.find((request) => request.put);
      if (put && this.items.length < this.capacity) {
        this.requests.splice(this.requests.indexOf(put), 1);
        this.items.push(put.element);
        put.done();
        moved = true;
      }
      const take = this.requests.find((request) => !request.put);
      if (take && this.items.length > 0) {
        this.requests.splice(this.requests.indexOf(take), 1);
        take.done(this.items.shift());
        moved = true;
      }
    }
  }

  enqueue(element) {
    return new Promise((done) => {
      this.requests.push({ put: true, element, done });
      this.serve();
    });
  }

  dequeue() {
    return new Promise((done) => {
      this.requests.push({ put: false, done });
      this.serve();
    });
  }

  size() {
    return this.items.length;
  }
}

