function generate(rand, size) {
  const pick = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const small = size === 'small';
  const producers = small ? pick(1, 3) : pick(1, 8);
  const consumers = small ? pick(1, 3) : pick(1, 8);
  const capacity = small ? pick(1, 3) : rand() < 0.2 ? pick(6, 30) : pick(1, 5);
  const calls = small ? pick(1, 10) : 40;
  // Keep dequeues <= enqueues <= dequeues + capacity so that every call can return.
  const dequeues = pick(Math.max(0, Math.ceil((calls - capacity) / 2)), Math.floor(calls / 2));
  const kinds = Array.from({ length: calls }, (_, i) => (i < dequeues ? 'dequeue' : 'enqueue'));
  for (let i = calls - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [kinds[i], kinds[j]] = [kinds[j], kinds[i]];
  }
  const operations = ['BoundedBlockingQueue', ...kinds];
  const args = [[capacity], ...kinds.map((kind) => (kind === 'enqueue' ? [pick(0, 20)] : []))];
  return [producers, consumers, operations, args];
}
